SELECT gen_random_uuid()::text, 'formula', '$i(t) = I_0\,e^{-Rt/L}$', 'Current Decay in an RL Circuit', '$i(t) = I_0\,e^{-Rt/L},\qquad v_L(t) = -RI_0\,e^{-Rt/L}$', '$\text{A}$', 'How an inductor''s current dies away through a resistor once the source is removed.', '[{"symbol":"$I_0$","meaning":"inductor current at the switching instant","unit":"$\\text{A}$"},{"symbol":"$R$","meaning":"resistance (Thévenin, seen by L or C)","unit":"$\\Omega$"},{"symbol":"$L$","meaning":"inductance","unit":"$\\text{H}$"},{"symbol":"$t$","meaning":"time after switching","unit":"$\\text{s}$"}]'::jsonb, 'The inductor voltage reverses to keep the current flowing. Open the circuit with no path and L di/dt arcs the switch: hence freewheeling diodes.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electrical Transient Analysis' AND t."subject" = 'EE' AND s."normKey" = 'rl transients' AND s."active"), NULL, false, 'PENDING', now(), now()
