SELECT gen_random_uuid()::text, 'formula', '$v_L(t) = V\,e^{-Rt/L}$', 'Inductor Voltage After a Step', '$v_L(t) = V\,e^{-Rt/L},\qquad v_R(t) = V\left(1 - e^{-Rt/L}\right)$', '$\text{V}$', 'At the first instant the whole step appears across the inductor; it then hands it over to the resistor.', '[{"symbol":"$V$","meaning":"step voltage","unit":"$\\text{V}$"},{"symbol":"$R$","meaning":"resistance (Thévenin, seen by L or C)","unit":"$\\Omega$"},{"symbol":"$L$","meaning":"inductance","unit":"$\\text{H}$"},{"symbol":"$t$","meaning":"time after the step","unit":"$\\text{s}$"}]'::jsonb, 'v_L + v_R = V at every instant: the two curves are mirror images.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electrical Transient Analysis' AND t."subject" = 'EE' AND s."normKey" = 'rl transients' AND s."active"), NULL, false, 'PENDING', now(), now()
