SELECT gen_random_uuid()::text, 'formula', '$x'''' + 2\alpha x'' + \omega_0^2x = \omega_0^2x_\infty$', 'Second-Order Circuit Equation', '$\frac{d^2x}{dt^2} + 2\alpha\frac{dx}{dt} + \omega_0^2x = \omega_0^2x_\infty;\qquad \text{series: } LC\,v_C'''' + RC\,v_C'' + v_C = V$', NULL, 'Every RLC circuit with a dc source fits this equation once α and ω₀ are found.', '[{"symbol":"$\\alpha$","meaning":"damping coefficient","unit":"$\\text{Np/s}$"},{"symbol":"$\\omega_0$","meaning":"undamped natural frequency","unit":"$\\text{rad/s}$"},{"symbol":"$x_\\infty$","meaning":"final (forced) value for a dc source","unit":null}]'::jsonb, 'Its roots are s = −α ± √(α² − ω₀²); the forced part is just the dc steady-state value.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electrical Transient Analysis' AND t."subject" = 'EE' AND s."normKey" = 'rlc transients' AND s."active"), NULL, true, 'PENDING', now(), now()
