SELECT gen_random_uuid()::text, 'formula', '$\alpha = \frac{1}{2RC}$', 'Damping Coefficient of a Parallel RLC Circuit', '$\alpha = \frac{1}{2RC},\qquad \omega_0 = \frac{1}{\sqrt{LC}}$', '$\text{Np/s}$', 'How fast a parallel RLC circuit''s response dies away.', '[{"symbol":"$\\alpha$","meaning":"damping coefficient","unit":"$\\text{Np/s}$"},{"symbol":"$R$","meaning":"resistance (Thévenin, seen by L or C)","unit":"$\\Omega$"},{"symbol":"$C$","meaning":"capacitance","unit":"$\\text{F}$"}]'::jsonb, 'A LARGER parallel R means LESS damping: the opposite of the series circuit, α = R/2L.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electrical Transient Analysis' AND t."subject" = 'EE' AND s."normKey" = 'rlc transients' AND s."active"), NULL, false, 'PENDING', now(), now()
