SELECT gen_random_uuid()::text, 'formula', '$x_n = e^{-\alpha t}(B_1\cos\omega_dt + B_2\sin\omega_dt)$', 'Natural Response Forms (Second Order)', '$\text{over: } A_1e^{s_1t} + A_2e^{s_2t};\quad \text{critical: } (D_1 + D_2t)e^{-\alpha t};\quad \text{under: } e^{-\alpha t}(B_1\cos\omega_dt + B_2\sin\omega_dt)$', NULL, 'The three shapes a second-order natural response can take.', '[{"symbol":"$s_1, s_2$","meaning":"real roots, −α ± √(α² − ω₀²)","unit":"$\\text{1/s}$"},{"symbol":"$\\alpha$","meaning":"damping coefficient","unit":"$\\text{Np/s}$"},{"symbol":"$\\omega_d$","meaning":"damped frequency","unit":"$\\text{rad/s}$"}]'::jsonb, 'Critical damping needs the t·e^(−αt) term: two equal roots, not one.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electrical Transient Analysis' AND t."subject" = 'EE' AND s."normKey" = 'natural and forced response' AND s."active"), NULL, true, 'PENDING', now(), now()
