SELECT gen_random_uuid()::text, 'formula', '$\zeta = \frac{\alpha}{\omega_0}$', 'Damping Ratio', '$\zeta = \frac{\alpha}{\omega_0} = \frac{R}{2}\sqrt{\frac{C}{L}}\ (\text{series}),\qquad \omega_d = \omega_0\sqrt{1 - \zeta^2},\qquad Q = \frac{1}{2\zeta}$', NULL, 'How damped a circuit is on one scale: above 1 overdamped, 1 critical, below 1 underdamped.', '[{"symbol":"$\\alpha$","meaning":"damping coefficient","unit":"$\\text{Np/s}$"},{"symbol":"$\\omega_0$","meaning":"undamped natural frequency","unit":"$\\text{rad/s}$"},{"symbol":"$R$","meaning":"resistance (Thévenin, seen by L or C)","unit":"$\\Omega$"},{"symbol":"$L$","meaning":"inductance","unit":"$\\text{H}$"},{"symbol":"$C$","meaning":"capacitance","unit":"$\\text{F}$"}]'::jsonb, 'For a series RLC, ζ = 1/(2Q): a high-Q circuit rings for many cycles.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electrical Transient Analysis' AND t."subject" = 'EE' AND s."normKey" = 'damping' AND s."active"), NULL, true, 'PENDING', now(), now()
