SELECT gen_random_uuid()::text, 'formula', '$\delta = \ln\frac{x_n}{x_{n+1}} = \alpha T_d$', 'Logarithmic Decrement', '$\delta = \ln\frac{x_n}{x_{n+1}} = \alpha T_d = \frac{2\pi\zeta}{\sqrt{1 - \zeta^2}},\qquad T_d = \frac{2\pi}{\omega_d}$', NULL, 'The damping read off a ringing waveform from the ratio of successive peaks.', '[{"symbol":"$x_n, x_{n+1}$","meaning":"two successive peaks, one period apart","unit":null},{"symbol":"$\\alpha$","meaning":"damping coefficient","unit":"$\\text{Np/s}$"},{"symbol":"$T_d$","meaning":"damped period","unit":"$\\text{s}$"},{"symbol":"$\\zeta$","meaning":"damping ratio, α/ω₀","unit":null}]'::jsonb, 'Measure two peaks one full period apart; peaks half a period apart alternate in sign.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electrical Transient Analysis' AND t."subject" = 'EE' AND s."normKey" = 'damping' AND s."active"), NULL, true, 'PENDING', now(), now()
