SELECT gen_random_uuid()::text, 'formula', '$R = \frac12\sqrt{\frac{L}{C}}$', 'Critical Resistance of a Parallel RLC Circuit', '$R_c = \frac12\sqrt{\frac{L}{C}}$', '$\Omega$', 'The parallel resistance that makes a parallel RLC circuit critically damped.', '[{"symbol":"$R_c$","meaning":"parallel resistance for critical damping","unit":"$\\Omega$"},{"symbol":"$L$","meaning":"inductance","unit":"$\\text{H}$"},{"symbol":"$C$","meaning":"capacitance","unit":"$\\text{F}$"}]'::jsonb, 'In parallel, LESS resistance than this is overdamped; in series it is MORE than 2√(L/C).', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electrical Transient Analysis' AND t."subject" = 'EE' AND s."normKey" = 'damping' AND s."active"), NULL, false, 'PENDING', now(), now()
