SELECT gen_random_uuid()::text, 'formula', '$v_C = V[1 - e^{-\alpha t}(\cos\omega_dt + \dots)]$', 'Underdamped Step Response of a Series RLC', '$v_C(t) = V\left[1 - e^{-\alpha t}\left(\cos\omega_dt + \frac{\alpha}{\omega_d}\sin\omega_dt\right)\right]$', '$\text{V}$', 'The capacitor voltage of an underdamped series RLC after a dc step, starting uncharged with no current.', '[{"symbol":"$V$","meaning":"step voltage","unit":"$\\text{V}$"},{"symbol":"$\\alpha$","meaning":"damping coefficient","unit":"$\\text{Np/s}$"},{"symbol":"$\\omega_d$","meaning":"damped frequency","unit":"$\\text{rad/s}$"}]'::jsonb, 'It overshoots V and rings about it at ω_d while the envelope decays as e^(−αt).', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electrical Transient Analysis' AND t."subject" = 'EE' AND s."normKey" = 'step and impulse response' AND s."active"), NULL, false, 'PENDING', now(), now()
