SELECT gen_random_uuid()::text, 'formula', '$\%OS = 100\,e^{-\pi\zeta/\sqrt{1 - \zeta^2}}$', 'Overshoot, Peak Time and Settling Time', '$\%OS = 100\,e^{-\pi\zeta/\sqrt{1 - \zeta^2}},\qquad t_p = \frac{\pi}{\omega_d},\qquad t_s \approx \frac{4}{\alpha}\ (2\%)$', NULL, 'How far an underdamped step response overshoots, when it peaks, and when it settles.', '[{"symbol":"$\\zeta$","meaning":"damping ratio, α/ω₀","unit":null},{"symbol":"$\\omega_d$","meaning":"damped frequency","unit":"$\\text{rad/s}$"},{"symbol":"$\\alpha$","meaning":"damping coefficient","unit":"$\\text{Np/s}$"}]'::jsonb, 'The overshoot depends on ζ alone: ζ = 0.5 gives 16.3%, ζ = 0.7 about 4.6%.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electrical Transient Analysis' AND t."subject" = 'EE' AND s."normKey" = 'step and impulse response' AND s."active"), NULL, true, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Electrical Transient Analysis' AND t."subject" = 'EE'
