SELECT gen_random_uuid()::text, 'formula', '$h(t) = \frac{d}{dt}s(t)$', 'Impulse Response from Step Response', '$h(t) = \frac{d}{dt}s(t),\qquad \delta(t) = \frac{du(t)}{dt},\qquad \mathcal{L}\{\delta\} = 1,\ \mathcal{L}\{u\} = \frac1s$', NULL, 'In a linear circuit the impulse response is the slope of the step response.', '[{"symbol":"$h(t)$","meaning":"impulse response","unit":null},{"symbol":"$s(t)$","meaning":"unit step response","unit":null},{"symbol":"$u(t)$","meaning":"unit step","unit":null}]'::jsonb, 'An impulse of current can change a capacitor''s voltage at once: q delivered in no time gives Δv = q/C.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electrical Transient Analysis' AND t."subject" = 'EE' AND s."normKey" = 'step and impulse response' AND s."active"), NULL, true, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Electrical Transient Analysis' AND t."subject" = 'EE'
