SELECT gen_random_uuid()::text, 'formula', '$h(t) = \frac{1}{RC}e^{-t/RC}$', 'Impulse Response of an RC Circuit', '$h(t) = \frac{1}{RC}\,e^{-t/RC}\,u(t)\quad (v_C \text{ for a unit voltage impulse})$', '$\text{1/s}$', 'The capacitor voltage after a unit impulse of source voltage: it jumps to 1/RC and decays.', '[{"symbol":"$R$","meaning":"resistance (Thévenin, seen by L or C)","unit":"$\\Omega$"},{"symbol":"$C$","meaning":"capacitance","unit":"$\\text{F}$"},{"symbol":"$t$","meaning":"time","unit":"$\\text{s}$"}]'::jsonb, 'Its area is 1, the same as the step response''s final value.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electrical Transient Analysis' AND t."subject" = 'EE' AND s."normKey" = 'step and impulse response' AND s."active"), NULL, false, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Electrical Transient Analysis' AND t."subject" = 'EE'
