SELECT gen_random_uuid()::text, 'formula', '$\frac{1}{s+a} \leftrightarrow e^{-at}$', 'Laplace Pairs for Transients', '$\frac{1}{s+a} \leftrightarrow e^{-at};\quad \frac{1}{(s+a)^2} \leftrightarrow te^{-at};\quad \frac{\omega}{(s+a)^2 + \omega^2} \leftrightarrow e^{-at}\sin\omega t;\quad \frac{s+a}{(s+a)^2 + \omega^2} \leftrightarrow e^{-at}\cos\omega t$', NULL, 'The four transforms that cover nearly every circuit transient.', '[{"symbol":"$a$","meaning":"decay rate (a pole at s = −a)","unit":"$\\text{1/s}$"},{"symbol":"$\\omega$","meaning":"ringing frequency","unit":"$\\text{rad/s}$"}]'::jsonb, 'Complete the square in a quadratic denominator to read α and ω_d straight off: (s + α)² + ω_d².', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electrical Transient Analysis' AND t."subject" = 'EE' AND s."normKey" = 'laplace transform solutions' AND s."active"), NULL, true, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Electrical Transient Analysis' AND t."subject" = 'EE'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
