SELECT gen_random_uuid()::text, 'formula', '$K_i = (s - p_i)F(s)\big|_{s = p_i}$', 'Partial Fractions by Cover-Up', '$F(s) = \sum_i\frac{K_i}{s - p_i},\qquad K_i = (s - p_i)F(s)\big|_{s = p_i}$', NULL, 'Splits a transform into simple terms that invert to exponentials, one residue at a time.', '[{"symbol":"$p_i$","meaning":"a simple pole of F(s)","unit":"$\\text{1/s}$"},{"symbol":"$K_i$","meaning":"its residue","unit":null}]'::jsonb, 'Make F(s) proper first. Complex poles come in conjugate pairs with conjugate residues.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electrical Transient Analysis' AND t."subject" = 'EE' AND s."normKey" = 'laplace transform solutions' AND s."active"), NULL, true, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Electrical Transient Analysis' AND t."subject" = 'EE'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
