SELECT gen_random_uuid()::text, 'formula', '$H(s) = \frac{Y(s)}{X(s)}$', 'Transfer Function', '$H(s) = \frac{Y(s)}{X(s)}\ (\text{zero initial conditions}),\qquad Y(s) = H(s)X(s),\qquad h(t) = \mathcal{L}^{-1}\{H(s)\}$', NULL, 'The output-to-input ratio of a circuit in the s-domain; its inverse is the impulse response.', '[{"symbol":"$X(s)$","meaning":"input transform","unit":null},{"symbol":"$Y(s)$","meaning":"output transform","unit":null}]'::jsonb, 'Stable only if every pole is in the left half-plane. Put s = jω to get the frequency response.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electrical Transient Analysis' AND t."subject" = 'EE' AND s."normKey" = 'transfer functions' AND s."active"), NULL, true, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Electrical Transient Analysis' AND t."subject" = 'EE'
