SELECT gen_random_uuid()::text, 'formula', '$H = \frac{\omega_0^2}{s^2 + 2\zeta\omega_0s + \omega_0^2}$', 'Standard Second-Order Transfer Function', '$H(s) = \frac{\omega_0^2}{s^2 + 2\zeta\omega_0s + \omega_0^2};\qquad \text{series RLC, } v_C: \frac{1/LC}{s^2 + (R/L)s + 1/LC}$', NULL, 'The second-order form a series RLC circuit''s capacitor voltage takes.', '[{"symbol":"$\\omega_0$","meaning":"undamped natural frequency","unit":"$\\text{rad/s}$"},{"symbol":"$\\zeta$","meaning":"damping ratio, α/ω₀","unit":null}]'::jsonb, 'Match the denominator term by term: 2ζω₀ = R/L and ω₀² = 1/LC.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electrical Transient Analysis' AND t."subject" = 'EE' AND s."normKey" = 'transfer functions' AND s."active"), NULL, true, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Electrical Transient Analysis' AND t."subject" = 'EE'
