SELECT gen_random_uuid()::text, 'formula', '$i = i_{ac} - \frac{V_m}{Z}\sin(\theta - \phi)e^{-Rt/L}$', 'Switching an AC Source into an RL Circuit', '$i(t) = \frac{V_m}{Z}\left[\sin(\omega t + \theta - \phi) - \sin(\theta - \phi)\,e^{-Rt/L}\right],\qquad \phi = \tan^{-1}\frac{\omega L}{R}$', '$\text{A}$', 'The current when a sinusoidal source is switched onto an RL circuit: steady ac plus a decaying dc offset.', '[{"symbol":"$V_m$","meaning":"peak source voltage","unit":"$\\text{V}$"},{"symbol":"$Z$","meaning":"√(R² + ω²L²)","unit":"$\\Omega$"},{"symbol":"$\\theta$","meaning":"voltage angle at the switching instant","unit":"$\\text{rad}$"},{"symbol":"$\\phi$","meaning":"impedance angle","unit":"$\\text{rad}$"}]'::jsonb, 'No offset if switched at θ = φ; the worst offset at θ − φ = ±90°, nearly a voltage zero in a highly inductive circuit.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electrical Transient Analysis' AND t."subject" = 'EE' AND s."normKey" = 'ac transients and switching' AND s."active"), NULL, false, 'PENDING', now(), now()
