SELECT gen_random_uuid()::text, 'formula', '$i_{pk} \approx \sqrt2\,I\left(1 + e^{-\pi R/X}\right)$', 'Peak Asymmetrical Current', '$i_{pk} \approx \sqrt2\,I\left(1 + e^{-\pi R/X}\right)$', '$\text{A}$', 'The first peak of a fully offset fault or switching current, about half a cycle after it starts.', '[{"symbol":"$I$","meaning":"symmetrical RMS current","unit":"$\\text{A}$"},{"symbol":"$X/R$","meaning":"reactance-to-resistance ratio of the circuit","unit":null}]'::jsonb, 'It approaches 2√2 I as X/R grows; breakers and busbars must withstand this peak, not just √2 I.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electrical Transient Analysis' AND t."subject" = 'EE' AND s."normKey" = 'ac transients and switching' AND s."active"), NULL, false, 'PENDING', now(), now()
