SELECT gen_random_uuid()::text, 'formula', '$i_{pk} = V_{pk}\sqrt{\frac{C}{L}}$', 'Capacitor Energizing Inrush', '$i_{pk} = V_{pk}\sqrt{\frac{C}{L}},\qquad f_{\text{inrush}} = \frac{1}{2\pi\sqrt{LC}},\qquad v_C \to 2V_{pk}$', '$\text{A}$', 'The inrush current and ringing when an uncharged capacitor bank is switched on at a voltage peak.', '[{"symbol":"$V_{pk}$","meaning":"voltage at the closing instant","unit":"$\\text{V}$"},{"symbol":"$L$","meaning":"inductance between source and capacitor","unit":"$\\text{H}$"},{"symbol":"$C$","meaning":"capacitance","unit":"$\\text{F}$"}]'::jsonb, 'The capacitor voltage can overshoot to about 2 pu; back-to-back banks see far larger inrush through the small L between them.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electrical Transient Analysis' AND t."subject" = 'EE' AND s."normKey" = 'ac transients and switching' AND s."active"), NULL, false, 'PENDING', now(), now()
