SELECT gen_random_uuid()::text, 'formula', '$V = I_{ch}\sqrt{\frac{L}{C}}$', 'Current Chopping Overvoltage', '$\tfrac12LI_{ch}^2 = \tfrac12CV^2 \implies V = I_{ch}\sqrt{\frac{L}{C}}$', '$\text{V}$', 'The overvoltage when a breaker cuts an inductive current before its natural zero.', '[{"symbol":"$I_{ch}$","meaning":"current at the instant it is chopped","unit":"$\\text{A}$"},{"symbol":"$L$","meaning":"inductance","unit":"$\\text{H}$"},{"symbol":"$C$","meaning":"stray capacitance across the inductance","unit":"$\\text{F}$"}]'::jsonb, 'The magnetic energy has nowhere to go but the small stray capacitance, so even a few amperes give large voltages.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electrical Transient Analysis' AND t."subject" = 'EE' AND s."normKey" = 'ac transients and switching' AND s."active"), NULL, false, 'PENDING', now(), now()
