SELECT gen_random_uuid()::text, 'formula', '$v = \frac{1}{\sqrt{LC}}$', 'Traveling Wave Velocity on a Line', '$v = \frac{1}{\sqrt{LC}}\ (\text{per unit length}),\qquad T = \frac{\ell}{v}$', '$\text{m/s}$', 'How fast a surge travels along a line, and how long it takes to reach the end.', '[{"symbol":"$L, C$","meaning":"inductance and capacitance per unit length","unit":"$\\text{H/m, F/m}$"},{"symbol":"$\\ell$","meaning":"line length","unit":"$\\text{m}$"},{"symbol":"$T$","meaning":"one-way travel time","unit":"$\\text{s}$"}]'::jsonb, 'Overhead lines: nearly c = 300 m/µs. Cables: c/√εᵣ, about half that.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electrical Transient Analysis' AND t."subject" = 'EE' AND s."normKey" = 'traveling waves' AND s."active"), NULL, false, 'PENDING', now(), now()
