SELECT gen_random_uuid()::text, 'formula', '$v^+ = V_s\frac{Z_0}{Z_s + Z_0}$', 'Surge Launched onto a Line', '$v^+ = V_s\frac{Z_0}{Z_s + Z_0},\qquad i^+ = \frac{v^+}{Z_0}$', '$\text{V}$', 'The voltage and current wave a source sends down a line before any reflection returns.', '[{"symbol":"$V_s$","meaning":"source voltage","unit":"$\\text{V}$"},{"symbol":"$Z_s$","meaning":"source impedance","unit":"$\\Omega$"},{"symbol":"$Z_0$","meaning":"surge (characteristic) impedance of the line","unit":"$\\Omega$"}]'::jsonb, 'Until a reflection comes back, the line looks like a resistor equal to Z₀, whatever is at the far end.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electrical Transient Analysis' AND t."subject" = 'EE' AND s."normKey" = 'traveling waves' AND s."active"), NULL, false, 'PENDING', now(), now()
