SELECT gen_random_uuid()::text, 'formula', '$\Gamma = \frac{Z_L - Z_0}{Z_L + Z_0}$', 'Reflection and Transmission Coefficients', '$\Gamma = \frac{Z_L - Z_0}{Z_L + Z_0},\qquad \tau = 1 + \Gamma = \frac{2Z_L}{Z_L + Z_0},\qquad \Gamma_i = -\Gamma$', NULL, 'What fraction of a surge reflects at a junction or termination, and what passes on.', '[{"symbol":"$Z_L$","meaning":"termination, or the next line''s Z₀ (lines in parallel combine)","unit":"$\\Omega$"},{"symbol":"$Z_0$","meaning":"surge (characteristic) impedance of the line","unit":"$\\Omega$"}]'::jsonb, 'Open end: Γ = +1, the voltage doubles. Short: Γ = −1. Matched (Z_L = Z₀): no reflection. The current reflects with the opposite sign.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electrical Transient Analysis' AND t."subject" = 'EE' AND s."normKey" = 'traveling waves' AND s."active"), NULL, true, 'PENDING', now(), now()
